WITH gaps AS (SELECT *, CASE WHEN reading_ts - LAG(reading_ts) OVER (PARTITION BY device_code ORDER BY reading_ts, id) > INTERVAL 15 MINUTES THEN 1 ELSE 0 END AS is_new_burst FROM device_readings), islands AS (SELECT *, SUM(is_new_burst) OVER (PARTITION BY device_code ORDER BY reading_ts, id ROWS BETWEEN UNBOUNDED PRECEDING AND CURRENT ROW) AS island_id FROM gaps) SELECT CASE WHEN temp_c >= 35.3 THEN 'PREMIUM' ELSE 'STANDARD' END AS temp_c_tier, MAX(temp_c) AS max_temp_c, PERCENTILE_APPROX(pressure, 0.95) AS pressure_p95, SIZE(COLLECT_SET(device_code)) AS num_device_codes, COUNT(*) AS cnt, APPROX_PERCENTILE(temp_c, 0.9) AS temp_c_p90, SUM(island_id) FILTER (WHERE device_code = 'DV-03') AS dv_03_total_island_id FROM islands GROUP BY CASE WHEN temp_c >= 35.3 THEN 'PREMIUM' ELSE 'STANDARD' END HAVING SUM(island_id) FILTER (WHERE device_code = 'DV-03') > 0 ORDER BY temp_c_p90 DESC;
